  padding:4px 14px;border-radius:999px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;max-width:280px}
.pf-shot{display:block;width:100%;aspect-ratio:16/10;object-fit:cover;transition:transform .35s}
